Get-AzWvdUserSession -ResourceGroupName 'sample-resourcegroupname' -HostPoolName 'sample-hostpoolname' -SessionHostName ('sample-sessionhostname' -split '/')[-1] | ForEach-Object { Send-AzWvdUserSessionMessage -ResourceGroupName 'sample-resourcegroupname' -HostPoolName 'sample-hostpoolname' -SessionHostName ('sample-sessionhostname' -split '/')[-1] -UserSessionId ($_.Name -split '/')[-1] -MessageTitle 'Maintenance' -MessageBody 'Please save your work and sign out within 30 minutes. This desktop will be restarted.' }
